// src/services/auth.js

import { jwtDecode } from "jwt-decode"; // Assurez-vous d'avoir installé 'jwt-decode' (npm install jwt-decode)

let navigateInstance = null;

export const setNavigateInstance = (navigate) => {
  navigateInstance = navigate;
};

/**
 * Effectue une requête API authentifiée.
 * Gère l'ajout du token d'authentification et la gestion des erreurs HTTP.
 * @param {string} url - L'URL de l'API.
 * @param {Object} options - Options de la requête fetch (méthode, corps, etc.).
 * @returns {Promise<Response>} - La réponse de l'API.
 * @throws {Error} - Lance une erreur si la requête échoue ou si la réponse n'est pas OK.
 */
export const apiRequest = async (url, options = {}) => {
  const token = localStorage.getItem("access_token");
  const headers = {
    "Content-Type": "application/json",
    ...options.headers,
  };

  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  try {
    const response = await fetch(url, {
      ...options,
      headers,
    });

    // Si la réponse n'est pas OK (statut 2xx), nous la considérons comme une erreur.
    if (!response.ok) {
      // Tente de parser le corps de la réponse comme JSON pour obtenir les détails de l'erreur.
      // Si ce n'est pas du JSON, utilise le texte brut.
      const errorText = await response.text();
      let errorData = { detail: `Erreur HTTP: ${response.status}` };
      try {
        errorData = JSON.parse(errorText);
      } catch (e) {
        // Si le corps n'est pas un JSON valide, utilise le texte brut comme détail.
        errorData.detail = errorText || errorData.detail;
      }

      // Gère spécifiquement les erreurs 401 (Non autorisé)
      if (response.status === 401) {
        console.error(
          "Accès non autorisé. Tentative de rafraîchissement du token ou déconnexion."
        );
        // Ici, vous pourriez implémenter une logique pour rafraîchir le token
        // Si le rafraîchissement échoue ou n'est pas implémenté, déconnectez l'utilisateur.
        logout(); // Assurez-vous que logout gère la navigation vers la page de connexion
        throw new Error(
          "Votre session a expiré ou n'est pas autorisée. Veuillez vous reconnecter."
        );
      }

      // Crée une nouvelle erreur avec les détails de la réponse pour une meilleure traçabilité.
      const error = new Error(
        errorData.detail || `Erreur API: ${response.status}`
      );
      error.response = response; // Attache l'objet de réponse pour un débogage plus approfondi
      error.data = errorData; // Attache les données d'erreur parsées
      throw error; // Lance l'erreur pour qu'elle soit capturée par le code appelant
    }

    return response; // Retourne l'objet Response si tout est OK
  } catch (error) {
    // Capture les erreurs réseau (ex: pas de connexion internet, serveur non joignable)
    console.error("Erreur de réseau ou de requête API:", error);
    // Relance l'erreur pour qu'elle soit gérée par les blocs try...catch dans Dashboard.jsx
    throw error;
  }
};

export const login = async (username, password) => {
  try {
    const response = await fetch("http://127.0.0.1:8000/api/auth/token/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ username, password }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.detail || "Échec de la connexion");
    }

    const data = await response.json();
    localStorage.setItem("access_token", data.access);
    localStorage.setItem("refresh_token", data.refresh);

    // Décode le token pour obtenir l'ID utilisateur, si nécessaire
    const decodedToken = jwtDecode(data.access);
    localStorage.setItem("user_id", decodedToken.user_id); // Stocke l'ID utilisateur

    if (navigateInstance) {
      navigateInstance("/dashboard");
    }
    return true;
  } catch (error) {
    console.error("Erreur de connexion:", error);
    throw error; // Relance l'erreur pour la gestion dans le composant de connexion
  }
};

export const logout = () => {
  localStorage.removeItem("access_token");
  localStorage.removeItem("refresh_token");
  localStorage.removeItem("user_id"); // Efface l'ID utilisateur à la déconnexion
  if (navigateInstance) {
    navigateInstance("/login");
  }
};

export const isAuthenticated = () => {
  const token = localStorage.getItem("access_token");
  if (!token) {
    return false;
  }
  try {
    const decodedToken = jwtDecode(token);
    // Vérifie si le token est expiré
    const currentTime = Date.now() / 1000;
    return decodedToken.exp > currentTime;
  } catch (error) {
    console.error("Erreur lors du décodage du token:", error);
    return false;
  }
};

// Fonction pour rafraîchir le token (si votre backend Django supporte le rafraîchissement de token JWT)
